class EWMAEstimator:
    def __init__(self, alpha):
        self.alpha = alpha
        self.state = None

    def observe(self, x):
        if self.state is None:
            self.state = x
        else:
            self.state = self.alpha * x + (1 - self.alpha) * self.state

    def value(self):
        return self.state
